package ec.espe.facturacion.adapters.in;
import com.fasterxml.jackson.databind.*; import com.fasterxml.jackson.core.type.TypeReference; import com.rabbitmq.client.*; import ec.espe.facturacion.application.CreateInvoiceCommand; import ec.espe.facturacion.domain.InvoiceLine; import java.math.BigDecimal; import java.nio.charset.StandardCharsets; import java.util.*;
public class AmqpAdapter {
 private final InvoiceService service; private final ObjectMapper json=new ObjectMapper().findAndRegisterModules(); public AmqpAdapter(InvoiceService s){service=s;}
 public void start(String uri,String queue)throws Exception { ConnectionFactory f=new ConnectionFactory(); f.setUri(uri); Connection c=f.newConnection(); Channel ch=c.createChannel(); ch.queueDeclare(queue,true,false,false,null); ch.basicQos(1); ch.basicConsume(queue,false,(tag,d)->{try{Map<String,Object> m=json.readValue(d.getBody(),new TypeReference<>(){});var lines=new ArrayList<InvoiceLine>();for(var raw:(List<Map<String,Object>>)m.getOrDefault("lines",List.of()))lines.add(new InvoiceLine((String)raw.get("description"),((Number)raw.get("quantity")).intValue(),new BigDecimal(raw.get("unitPrice").toString())));service.create(new CreateInvoiceCommand((String)m.get("operationId"),(String)m.get("customerId"),lines));ch.basicAck(d.getEnvelope().getDeliveryTag(),false);}catch(Exception e){System.err.println("Mensaje rechazado: "+e.getMessage());ch.basicNack(d.getEnvelope().getDeliveryTag(),false,false);}},tag->{}); System.out.println("AMQP consumiendo cola "+queue); }
}